-- Verified clinical field changes, 19 Nov 2026. All guards must pass together.
DO $content_audit$
BEGIN
  IF EXISTS (SELECT 1 FROM public.drugs WHERE id = '99bbc499-4a1f-4c3f-a18d-0257a57040ee' AND adult_bolus_dose IS NOT DISTINCT FROM 'Adults with severe or moderately severe symptoms attributable to hyponatraemia require urgent senior-supervised treatment in a monitored setting. The Society for Endocrinology uses 150 mL of 3% sodium chloride IV over 20 minutes (or a pharmacy-confirmed equivalent). Recheck serum sodium after the first bolus. Repeat as indicated by symptoms and measured sodium, aiming for an initial rise of 5 mmol/L in the first hour.'
      AND infusion_range IS NOT DISTINCT FROM 'Adult symptomatic hyponatraemia uses monitored intermittent boluses in the cited UK pathway. Raised ICP is a separate indication. The neurocritical-care guideline does not establish one continuous dose or sodium target for every cause of cerebral oedema. Use the cause-specific neurocritical-care protocol and confirmed concentration.'
      AND dosing IS NOT DISTINCT FROM 'Adults with severe or moderately severe symptoms attributable to hyponatraemia require urgent senior-supervised treatment in a monitored setting. The Society for Endocrinology uses 150 mL of 3% sodium chloride IV over 20 minutes (or a pharmacy-confirmed equivalent). Recheck serum sodium after the first bolus. Repeat as indicated by symptoms and measured sodium, aiming for an initial rise of 5 mmol/L in the first hour.
After the initial response, manage the cause. Limit the rise to 10 mmol/L in the first 24 hours and 8 mmol/L in each subsequent 24 hours. Persistent severe symptoms or overcorrection need immediate specialist reassessment. For raised ICP, use the diagnosis-specific neurocritical-care pathway. Do not transfer 3% volumes to a 5% preparation.'
      AND monitoring IS NOT DISTINCT FROM 'Recheck sodium after the first 20-minute bolus and serially during active correction. Follow the Society for Endocrinology algorithm for symptoms, subsequent boluses and more frequent checks if overcorrection is likely. Monitor fluid balance, neurological state, vital signs and IV site. In raised ICP, monitor according to the neurocritical-care protocol.'
      AND sources IS NOT DISTINCT FROM '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Hypertonic saline (3%/5%) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=hypertonic+saline"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Hypertonic saline (3%/5%) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=hypertonic+saline"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Hypertonic saline (3%/5%) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=hypertonic+saline"},{"title":"Emergency management of severe and moderately severely symptomatic hyponatraemia in adult patients, Figures 1 and 2 (2022)","url":"https://www.endocrinology.org/media/xhrhxhxm/emergency-management-of-severe-and-moderately-severely-symptomatic-hyponatraemia-in-adult-patients-2022.pdf","publisher":"Society for Endocrinology","accessed":"2026-11-19"},{"title":"Cook et al. Guidelines for the Acute Treatment of Cerebral Edema in Neurocritical Care Patients (2020), PMID 32227294","url":"https://pubmed.ncbi.nlm.nih.gov/32227294/","publisher":"Neurocritical Care Society","accessed":"2026-11-19"}]'::jsonb) THEN NULL;
  ELSE
    UPDATE public.drugs SET adult_bolus_dose = 'Adults with severe or moderately severe symptoms attributable to hyponatraemia require urgent senior-supervised treatment in a monitored setting. The Society for Endocrinology uses 150 mL of 3% sodium chloride IV over 20 minutes (or a pharmacy-confirmed equivalent). Recheck serum sodium after the first bolus. Repeat as indicated by symptoms and measured sodium, aiming for an initial rise of 5 mmol/L in the first hour.',
      infusion_range = 'Adult symptomatic hyponatraemia uses monitored intermittent boluses in the cited UK pathway. Raised ICP is a separate indication. The neurocritical-care guideline does not establish one continuous dose or sodium target for every cause of cerebral oedema. Use the cause-specific neurocritical-care protocol and confirmed concentration.',
      dosing = 'Adults with severe or moderately severe symptoms attributable to hyponatraemia require urgent senior-supervised treatment in a monitored setting. The Society for Endocrinology uses 150 mL of 3% sodium chloride IV over 20 minutes (or a pharmacy-confirmed equivalent). Recheck serum sodium after the first bolus. Repeat as indicated by symptoms and measured sodium, aiming for an initial rise of 5 mmol/L in the first hour.
After the initial response, manage the cause. Limit the rise to 10 mmol/L in the first 24 hours and 8 mmol/L in each subsequent 24 hours. Persistent severe symptoms or overcorrection need immediate specialist reassessment. For raised ICP, use the diagnosis-specific neurocritical-care pathway. Do not transfer 3% volumes to a 5% preparation.',
      monitoring = 'Recheck sodium after the first 20-minute bolus and serially during active correction. Follow the Society for Endocrinology algorithm for symptoms, subsequent boluses and more frequent checks if overcorrection is likely. Monitor fluid balance, neurological state, vital signs and IV site. In raised ICP, monitor according to the neurocritical-care protocol.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Hypertonic saline (3%/5%) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=hypertonic+saline"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Hypertonic saline (3%/5%) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=hypertonic+saline"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Hypertonic saline (3%/5%) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=hypertonic+saline"},{"title":"Emergency management of severe and moderately severely symptomatic hyponatraemia in adult patients, Figures 1 and 2 (2022)","url":"https://www.endocrinology.org/media/xhrhxhxm/emergency-management-of-severe-and-moderately-severely-symptomatic-hyponatraemia-in-adult-patients-2022.pdf","publisher":"Society for Endocrinology","accessed":"2026-11-19"},{"title":"Cook et al. Guidelines for the Acute Treatment of Cerebral Edema in Neurocritical Care Patients (2020), PMID 32227294","url":"https://pubmed.ncbi.nlm.nih.gov/32227294/","publisher":"Neurocritical Care Society","accessed":"2026-11-19"}]'::jsonb, updated_at=now()
    WHERE id = '99bbc499-4a1f-4c3f-a18d-0257a57040ee' AND slug = 'hypertonic-saline'
      AND adult_bolus_dose IS NOT DISTINCT FROM '• Acute symptomatic hyponatraemia: 150 mL of 3% sodium chloride IV over 20 minutes. May be repeated up to twice to achieve an initial 5 mmol/L rise in serum sodium within the first hour (BNF).
• Raised ICP: 2-4 mL/kg of 3% sodium chloride IV over 10-20 minutes (anaesthetic practice).'
      AND infusion_range IS NOT DISTINCT FROM '• Raised ICP: 0.1-1.0 mL/kg/hour of 3% sodium chloride (or 5% sodium chloride at 0.05-0.5 mL/kg/hour), titrated to ICP and serum sodium (anaesthetic practice).'
      AND dosing IS NOT DISTINCT FROM '• Acute symptomatic hyponatraemia: Initial 150 mL of 3% sodium chloride IV over 20 minutes. May be repeated up to twice. Aim for an initial 5 mmol/L rise in serum sodium within the first hour. Total rise should not exceed 10 mmol/L in 24 hours and 18 mmol/L in 48 hours (BNF).
• Acute raised ICP: 2-4 mL/kg 3% sodium chloride IV bolus over 10-20 minutes. May be repeated or followed by continuous infusion, guided by ICP and serum sodium (anaesthetic practice).'
      AND monitoring IS NOT DISTINCT FROM '• Serum sodium: Every 2-6 hours initially, then adjusted according to response. Aim for a maximum 10 mmol/L rise in serum sodium over 24 hours and 18 mmol/L in 48 hours (BNF).
• Fluid balance: Monitor urine output, daily weight. Central venous pressure (CVP) monitoring where indicated.
• Cardiovascular monitoring: Blood pressure, heart rate, signs of fluid overload.
• Neurological status: Glasgow Coma Scale (GCS), ICP monitoring where indicated.
• Infusion site: Regular inspection for extravasation/phlebitis, especially with peripheral administration.'
      AND sources IS NOT DISTINCT FROM '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Hypertonic saline (3%/5%) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=hypertonic+saline"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Hypertonic saline (3%/5%) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=hypertonic+saline"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Hypertonic saline (3%/5%) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=hypertonic+saline"}]'::jsonb;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unexpected content for drugs 99bbc499-4a1f-4c3f-a18d-0257a57040ee'; END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM public.drugs WHERE id = 'b07cac31-7de3-40ba-81dd-ac1c8efa7606' AND adult_bolus_dose IS NOT DISTINCT FROM 'Named US ready-to-administer injection, adult label. Give 0.25 mg/kg actual body weight IV over 2 minutes. For an inadequate response after 15 minutes the second dose is 0.35 mg/kg over 2 minutes. Continuous ECG and frequent BP measurement are required. Confirm the supplied product and local protocol before use.'
      AND infusion_range IS NOT DISTINCT FROM 'Named US ready-to-administer product: after the bolus, start at 5 mg/hour and titrate in 5 mg/hour steps as needed and tolerated to 15 mg/hour maximum. Infusions longer than 24 hours have not been studied in this label.'
      AND dosing IS NOT DISTINCT FROM 'Named US ready-to-administer injection, adult label. Give 0.25 mg/kg actual body weight IV over 2 minutes. For an inadequate response after 15 minutes the second dose is 0.35 mg/kg over 2 minutes. Continuous ECG and frequent BP measurement are required. Confirm the supplied product and local protocol before use.
For this product, start the infusion at 5 mg/hour following the bolus and titrate in 5 mg/hour steps, up to 15 mg/hour. Transition to an appropriate subsequent strategy within 24 hours. UK RCUK guidance lists diltiazem as one rate-control option for probable AF with ejection fraction above 40% in the stable irregular narrow-complex pathway. Avoid in pre-excited AF. This US label does not establish UK product availability.'
      AND sources IS NOT DISTINCT FROM '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Diltiazem — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=diltiazem"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Diltiazem — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=diltiazem"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Diltiazem — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=diltiazem"},{"title":"Diltiazem hydrochloride in sodium chloride injection, US prescribing information §§1–4 (premixed product)","url":"https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=8bae87a5-2137-467e-a1ad-79b2bc075e07","publisher":"DailyMed, US National Library of Medicine","accessed":"2026-11-19"},{"title":"Adult tachyarrhythmia algorithm, January 2026 revision","url":"https://www.resus.org.uk/sites/default/files/2026-01/Adult%20tachyarrhythmia%20algorithm%20V2%20January%202026.pdf","publisher":"Resuscitation Council UK","accessed":"2026-11-19"}]'::jsonb) THEN NULL;
  ELSE
    UPDATE public.drugs SET adult_bolus_dose = 'Named US ready-to-administer injection, adult label. Give 0.25 mg/kg actual body weight IV over 2 minutes. For an inadequate response after 15 minutes the second dose is 0.35 mg/kg over 2 minutes. Continuous ECG and frequent BP measurement are required. Confirm the supplied product and local protocol before use.',
      infusion_range = 'Named US ready-to-administer product: after the bolus, start at 5 mg/hour and titrate in 5 mg/hour steps as needed and tolerated to 15 mg/hour maximum. Infusions longer than 24 hours have not been studied in this label.',
      dosing = 'Named US ready-to-administer injection, adult label. Give 0.25 mg/kg actual body weight IV over 2 minutes. For an inadequate response after 15 minutes the second dose is 0.35 mg/kg over 2 minutes. Continuous ECG and frequent BP measurement are required. Confirm the supplied product and local protocol before use.
For this product, start the infusion at 5 mg/hour following the bolus and titrate in 5 mg/hour steps, up to 15 mg/hour. Transition to an appropriate subsequent strategy within 24 hours. UK RCUK guidance lists diltiazem as one rate-control option for probable AF with ejection fraction above 40% in the stable irregular narrow-complex pathway. Avoid in pre-excited AF. This US label does not establish UK product availability.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Diltiazem — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=diltiazem"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Diltiazem — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=diltiazem"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Diltiazem — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=diltiazem"},{"title":"Diltiazem hydrochloride in sodium chloride injection, US prescribing information §§1–4 (premixed product)","url":"https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=8bae87a5-2137-467e-a1ad-79b2bc075e07","publisher":"DailyMed, US National Library of Medicine","accessed":"2026-11-19"},{"title":"Adult tachyarrhythmia algorithm, January 2026 revision","url":"https://www.resus.org.uk/sites/default/files/2026-01/Adult%20tachyarrhythmia%20algorithm%20V2%20January%202026.pdf","publisher":"Resuscitation Council UK","accessed":"2026-11-19"}]'::jsonb, updated_at=now()
    WHERE id = 'b07cac31-7de3-40ba-81dd-ac1c8efa7606' AND slug = 'diltiazem'
      AND adult_bolus_dose IS NOT DISTINCT FROM '• Initial: 0.25 mg/kg IV over 2 minutes (typical 15–20 mg, max 25 mg).
• If response inadequate after 15 minutes, a second bolus of 0.35 mg/kg IV over 2 minutes may be given (typical 20–25 mg, max 35 mg).'
      AND infusion_range IS NOT DISTINCT FROM '• Initial: 5–15 mg/hour IV. Titrate to heart rate and blood pressure response.
• Usual range: 5–15 mg/hour IV. Maximum cumulative dose: 300 mg/24 hours (including boluses).'
      AND dosing IS NOT DISTINCT FROM '• Adult: Initial IV bolus 0.25 mg/kg (max 25 mg) over 2 min. If inadequate response, second bolus 0.35 mg/kg (max 35 mg) after 15 min. Follow with IV infusion of 5–15 mg/hour, titrated to heart rate and blood pressure, max 300 mg/24 hours (including boluses).
• Elderly: Use with caution; monitor closely for hypotension and bradycardia. Lower doses may be required.
• Hepatic impairment: Use with caution. Dosage reduction may be needed in severe impairment. Monitor ECG and blood pressure closely.
• Renal impairment: No specific dose adjustment but use with caution. Monitor ECG and blood pressure closely.'
      AND sources IS NOT DISTINCT FROM '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Diltiazem — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=diltiazem"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Diltiazem — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=diltiazem"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Diltiazem — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=diltiazem"}]'::jsonb;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unexpected content for drugs b07cac31-7de3-40ba-81dd-ac1c8efa7606'; END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM public.drugs WHERE id = 'b0851318-4385-4e69-b85f-12ec8af5b5cb' AND adult_bolus_dose IS NOT DISTINCT FROM 'UK Association of Anaesthetists QRH 3-10. For severe LAST, the initial IV dose of 20% lipid emulsion is 1.5 mL/kg, given over 2–3 minutes.'
      AND infusion_range IS NOT DISTINCT FROM 'Start at 15 mL/kg/hour. If circulation remains unstable or deteriorates, repeat the original bolus at 5 and 10 minutes as indicated. After 5 minutes the infusion may be increased to 30 mL/kg/hour for persistent or recurrent instability. Count all boluses and infusion towards the 12 mL/kg cumulative maximum.'
      AND key_warning IS NOT DISTINCT FROM 'For the UK Association of Anaesthetists LAST pathway, use 20% lipid emulsion. Maximum total volume is 12 mL/kg including boluses and infusion. Propofol cannot replace lipid rescue.'
      AND dosing IS NOT DISTINCT FROM 'UK Association of Anaesthetists QRH 3-10. For severe LAST, the initial IV dose of 20% lipid emulsion is 1.5 mL/kg, given over 2–3 minutes. Start at 15 mL/kg/hour. If circulation remains unstable or deteriorates, repeat the original bolus at 5 and 10 minutes as indicated. After 5 minutes the infusion may be increased to 30 mL/kg/hour for persistent or recurrent instability. Count all boluses and infusion towards the 12 mL/kg cumulative maximum. In arrest, give CPR, reduce IV adrenaline to no more than 1 microgram/kg per dose and avoid vasopressin. Follow the complete emergency algorithm.'
      AND sources IS NOT DISTINCT FROM '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Lipid emulsion (Intralipid 20%) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=intralipid"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Lipid emulsion (Intralipid 20%) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=intralipid"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Lipid emulsion (Intralipid 20%) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=intralipid"},{"accessed":"2026-10-30","publisher":"www.resus.org.uk","title":"Lipid emulsion (Intralipid 20%) — targeted dosing/safety source (Local anaesthetic systemic toxicity)","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines"},{"title":"Severe local anaesthetic toxicity, QRH 3-10 v2, Box A (June 2023)","url":"https://anaesthetists.org/Portals/0/PDFs/QRH/QRH_3-10_Local_anaesthetic_toxicity_v2_June%202023.pdf?ver=2023-06-23-141010-760","publisher":"Association of Anaesthetists","accessed":"2026-11-19"}]'::jsonb) THEN NULL;
  ELSE
    UPDATE public.drugs SET adult_bolus_dose = 'UK Association of Anaesthetists QRH 3-10. For severe LAST, the initial IV dose of 20% lipid emulsion is 1.5 mL/kg, given over 2–3 minutes.',
      infusion_range = 'Start at 15 mL/kg/hour. If circulation remains unstable or deteriorates, repeat the original bolus at 5 and 10 minutes as indicated. After 5 minutes the infusion may be increased to 30 mL/kg/hour for persistent or recurrent instability. Count all boluses and infusion towards the 12 mL/kg cumulative maximum.',
      key_warning = 'For the UK Association of Anaesthetists LAST pathway, use 20% lipid emulsion. Maximum total volume is 12 mL/kg including boluses and infusion. Propofol cannot replace lipid rescue.',
      dosing = 'UK Association of Anaesthetists QRH 3-10. For severe LAST, the initial IV dose of 20% lipid emulsion is 1.5 mL/kg, given over 2–3 minutes. Start at 15 mL/kg/hour. If circulation remains unstable or deteriorates, repeat the original bolus at 5 and 10 minutes as indicated. After 5 minutes the infusion may be increased to 30 mL/kg/hour for persistent or recurrent instability. Count all boluses and infusion towards the 12 mL/kg cumulative maximum. In arrest, give CPR, reduce IV adrenaline to no more than 1 microgram/kg per dose and avoid vasopressin. Follow the complete emergency algorithm.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Lipid emulsion (Intralipid 20%) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=intralipid"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Lipid emulsion (Intralipid 20%) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=intralipid"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Lipid emulsion (Intralipid 20%) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=intralipid"},{"accessed":"2026-10-30","publisher":"www.resus.org.uk","title":"Lipid emulsion (Intralipid 20%) — targeted dosing/safety source (Local anaesthetic systemic toxicity)","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines"},{"title":"Severe local anaesthetic toxicity, QRH 3-10 v2, Box A (June 2023)","url":"https://anaesthetists.org/Portals/0/PDFs/QRH/QRH_3-10_Local_anaesthetic_toxicity_v2_June%202023.pdf?ver=2023-06-23-141010-760","publisher":"Association of Anaesthetists","accessed":"2026-11-19"}]'::jsonb, updated_at=now()
    WHERE id = 'b0851318-4385-4e69-b85f-12ec8af5b5cb' AND slug = 'intralipid'
      AND adult_bolus_dose IS NOT DISTINCT FROM '1.5 mL/kg IV over 1 minute (ideal body weight). Repeat bolus up to two times if cardiovascular stability is not achieved.'
      AND infusion_range IS NOT DISTINCT FROM '• Initial infusion: 0.25 mL/kg/minute (ideal body weight).
• If cardiovascular instability persists, increase to 0.5 mL/kg/minute for up to 30 minutes.
• Continue for at least 10 minutes after cardiovascular stability, or for 30 minutes after the initial bolus.'
      AND key_warning IS NOT DISTINCT FROM 'Use ideal body weight for dosing; maximum 1000 mL in adults or 12.5 mL/kg in children (whichever is less) over the first 30 minutes.'
      AND dosing IS NOT DISTINCT FROM 'Local anaesthetic systemic toxicity (RCUK 2025; 20% lipid emulsion):
• Give an initial IV bolus of 1.5 mL/kg, followed by an infusion at 15 mL/kg/hour (0.25 mL/kg/minute).
• If needed, repeat the bolus up to twice at 5-minute intervals and increase the infusion to 30 mL/kg/hour (0.5 mL/kg/minute).
• Continue until the patient is stable or a maximum total dose of 12 mL/kg has been given.
• Follow the complete LAST resuscitation algorithm; do not combine the former 12.5 mL/kg or 1000 mL limits with this RCUK regimen.'
      AND sources IS NOT DISTINCT FROM '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Lipid emulsion (Intralipid 20%) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=intralipid"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Lipid emulsion (Intralipid 20%) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=intralipid"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Lipid emulsion (Intralipid 20%) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=intralipid"},{"accessed":"2026-10-30","publisher":"www.resus.org.uk","title":"Lipid emulsion (Intralipid 20%) — targeted dosing/safety source (Local anaesthetic systemic toxicity)","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines"}]'::jsonb;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unexpected content for drugs b0851318-4385-4e69-b85f-12ec8af5b5cb'; END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM public.drugs WHERE id = '04b80f49-6937-4424-8034-24be01996ab5' AND adult_bolus_dose IS NOT DISTINCT FROM 'RCUK January 2026 adult algorithm for stable, regular, narrow-complex tachyarrhythmia: after ineffective vagal manoeuvres, and only in the absence of pre-excitation, give rapid IV adenosine 6 mg, then 12 mg, then 18 mg if unsuccessful. Life-threatening features lead to the synchronised cardioversion pathway. The named Wockhardt product label uses a separate 3 mg, 6 mg, 12 mg schedule.'
      AND dosing IS NOT DISTINCT FROM 'RCUK January 2026 adult algorithm for stable, regular, narrow-complex tachyarrhythmia: after ineffective vagal manoeuvres, and only in the absence of pre-excitation, give rapid IV adenosine 6 mg, then 12 mg, then 18 mg if unsuccessful. Life-threatening features lead to the synchronised cardioversion pathway. The named Wockhardt product label uses a separate 3 mg, 6 mg, 12 mg schedule.
Named Wockhardt product schedule (current resuscitation algorithms may differ):
• Adults: Initial 3 mg IV bolus. If no effect after 1–2 minutes, 6 mg IV bolus. If no effect after 1–2 minutes, 12 mg IV bolus (maximum single dose 12 mg).
• Children 0–18 years, named product: first IV bolus 0.1 mg/kg (maximum 6 mg), then increments of 0.1 mg/kg as needed (maximum 12 mg per dose), with continuous ECG and immediate resuscitation capability. Use the adopted paediatric tachycardia protocol for full timing and escalation; do not blend different schedules.
• Elderly/Renal/Hepatic impairment: No specific dose adjustment necessary due to rapid clearance. Dipyridamole markedly potentiates adenosine: the product advises avoiding coadministration; if essential, withhold dipyridamole 24 hours beforehand when clinically feasible or greatly reduce adenosine under specialist guidance. A 3 mg dose is the ordinary starting dose in this schedule, not an established reduced dipyridamole dose. Recent heart transplantation also increases sensitivity; use the appropriate specialist algorithm.'
      AND sources IS NOT DISTINCT FROM '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Adenosine — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=adenosine"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Adenosine — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=adenosine"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Adenosine — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=adenosine"},{"accessed":"2026-10-30","publisher":"Official or primary clinical source","title":"Adenosine — Wockhardt SmPC 4.2/4.4/4.5, updated 4August 2023: valid 3/6/12 mg and dipyridamole interaction","url":"https://www.medicines.org.uk/emc/product/4766/smpc"},{"title":"Adult tachyarrhythmia algorithm, January 2026 revision","url":"https://www.resus.org.uk/sites/default/files/2026-01/Adult%20tachyarrhythmia%20algorithm%20V2%20January%202026.pdf","publisher":"Resuscitation Council UK","accessed":"2026-11-19"}]'::jsonb) THEN NULL;
  ELSE
    UPDATE public.drugs SET adult_bolus_dose = 'RCUK January 2026 adult algorithm for stable, regular, narrow-complex tachyarrhythmia: after ineffective vagal manoeuvres, and only in the absence of pre-excitation, give rapid IV adenosine 6 mg, then 12 mg, then 18 mg if unsuccessful. Life-threatening features lead to the synchronised cardioversion pathway. The named Wockhardt product label uses a separate 3 mg, 6 mg, 12 mg schedule.',
      dosing = 'RCUK January 2026 adult algorithm for stable, regular, narrow-complex tachyarrhythmia: after ineffective vagal manoeuvres, and only in the absence of pre-excitation, give rapid IV adenosine 6 mg, then 12 mg, then 18 mg if unsuccessful. Life-threatening features lead to the synchronised cardioversion pathway. The named Wockhardt product label uses a separate 3 mg, 6 mg, 12 mg schedule.
Named Wockhardt product schedule (current resuscitation algorithms may differ):
• Adults: Initial 3 mg IV bolus. If no effect after 1–2 minutes, 6 mg IV bolus. If no effect after 1–2 minutes, 12 mg IV bolus (maximum single dose 12 mg).
• Children 0–18 years, named product: first IV bolus 0.1 mg/kg (maximum 6 mg), then increments of 0.1 mg/kg as needed (maximum 12 mg per dose), with continuous ECG and immediate resuscitation capability. Use the adopted paediatric tachycardia protocol for full timing and escalation; do not blend different schedules.
• Elderly/Renal/Hepatic impairment: No specific dose adjustment necessary due to rapid clearance. Dipyridamole markedly potentiates adenosine: the product advises avoiding coadministration; if essential, withhold dipyridamole 24 hours beforehand when clinically feasible or greatly reduce adenosine under specialist guidance. A 3 mg dose is the ordinary starting dose in this schedule, not an established reduced dipyridamole dose. Recent heart transplantation also increases sensitivity; use the appropriate specialist algorithm.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Adenosine — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=adenosine"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Adenosine — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=adenosine"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Adenosine — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=adenosine"},{"accessed":"2026-10-30","publisher":"Official or primary clinical source","title":"Adenosine — Wockhardt SmPC 4.2/4.4/4.5, updated 4August 2023: valid 3/6/12 mg and dipyridamole interaction","url":"https://www.medicines.org.uk/emc/product/4766/smpc"},{"title":"Adult tachyarrhythmia algorithm, January 2026 revision","url":"https://www.resus.org.uk/sites/default/files/2026-01/Adult%20tachyarrhythmia%20algorithm%20V2%20January%202026.pdf","publisher":"Resuscitation Council UK","accessed":"2026-11-19"}]'::jsonb, updated_at=now()
