  IF EXISTS (SELECT 1 FROM public.drugs WHERE id = '9bbb2af9-38c8-4979-8a07-4dc93d32a51d' AND indication_oneliner IS NOT DISTINCT FROM 'Emergency treatment of a malignant hyperthermia crisis. For elective anaesthesia in a susceptible patient, use a trigger-free technique. EMHG advises against prophylactic dantrolene.'
