  IF EXISTS (SELECT 1 FROM public.viva_model_answers WHERE id = '3cf9e1f4-4816-42a7-a86b-d1aa29e2e3f5' AND model_answer IS NOT DISTINCT FROM 'Local Anaesthetic Systemic Toxicity (LAST) occurs when plasma levels of local anaesthetic reach a critical threshold, either through accidental intravascular injection or rapid absorption from highly vascular sites. Toxicity primarily affects the CNS and Cardiovascular systems.

