  IF EXISTS (SELECT 1 FROM public.viva_model_answers WHERE id = 'c35aa9ac-b410-4cb3-90cb-a737025f7432' AND model_answer IS NOT DISTINCT FROM 'Local anaesthetics are agents that reversibly block nerve impulse conduction. Structurally, they consist of a lipophilic aromatic ring, an intermediate chain (ester or amide), and a hydrophilic tertiary amine. In the UK, we primarily use amides like lidocaine and bupivacaine.

