      AND pitfalls IS NOT DISTINCT FROM '["Confusing MH with thyroid storm or neuroleptic malignant syndrome.","Delaying Dantrolene administration while waiting for a temperature rise.","Delaying dantrolene and oxygenation to change the circuit or machine."]'::jsonb) THEN NULL;
